changeSet.sql:
CREATE TABLE funcionarios (
id_funcionario NUMBER PRIMARY KEY,
nome VARCHAR2(100) NOT NULL,
contato VARCHAR2(15) NOT NULL,
disponibilidade VARCHAR2(50) NOT NULL
);

CREATE TABLE clientes (
id_cliente NUMBER PRIMARY KEY,
nome VARCHAR2(100) NOT NULL,
contato VARCHAR2(15) NOT NULL,
endereco VARCHAR2(200) NOT NULL
);

CREATE TABLE itens_menu (
id_item_menu NUMBER PRIMARY KEY,
nome VARCHAR2(100) NOT NULL,
descricao VARCHAR2(200) NOT NULL,
preco NUMBER(10, 2) NOT NULL
);

CREATE TABLE logs (
id_log NUMBER PRIMARY KEY,
tabela VARCHAR2(50) NOT NULL,
acao VARCHAR2(200) NOT NULL,
data_hora TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE SEQUENCE seq_restaurante START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_funcionario START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_cliente START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_pedido START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_item_menu START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_item_pedido START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_entrega START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_pagamento START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE seq_log START WITH 1 INCREMENT BY 1;

-- Inserts

-- Restaurantes
INSERT INTO restaurantes (id_restaurante, nome, endereco, contato, horario_abertura, horario_fechamento)
VALUES (seq_restaurante.NEXTVAL, 'Restaurante Sabor Caseiro', 'Rua Principal, 123', '99999-0001', TO_DATE('08:00', 'HH24:MI'), TO_DATE('20:00', 'HH24:MI'));

-- Funcionários
INSERT INTO funcionarios (id_funcionario, nome, contato, disponibilidade)
VALUES (seq_funcionario.NEXTVAL, 'João Silva', '99999-0002', 'DISPONIVEL');

INSERT INTO funcionarios (id_funcionario, nome, contato, disponibilidade)
VALUES (seq_funcionario.NEXTVAL, 'Maria Oliveira', '99999-0003', 'INDISPONIVEL');

-- Clientes
INSERT INTO clientes (id_cliente, nome, contato, endereco)
VALUES (seq_cliente.NEXTVAL, 'Carlos Santos', '99999-0004', 'Rua Nova, 456');

INSERT INTO clientes (id_cliente, nome, contato, endereco)
VALUES (seq_cliente.NEXTVAL, 'Ana Souza', '99999-0005', 'Avenida Central, 789');

-- Itens do Menu
INSERT INTO itens_menu (id_item_menu, nome, descricao, preco)
VALUES (seq_item_menu.NEXTVAL, 'Prato Executivo', 'Arroz, feijão, carne e salada', 25.50);

INSERT INTO itens_menu (id_item_menu, nome, descricao, preco)
VALUES (seq_item_menu.NEXTVAL, 'Prato Light', 'Arroz integral, frango grelhado e legumes', 30.00);

-- Pedidos
INSERT INTO pedidos (id_pedido, id_cliente, data_pedido, status_pedido, endereco_entrega, desconto)
VALUES (seq_pedido.NEXTVAL, 1, SYSDATE, 'FINALIZADO', 'Rua Nova, 456', 5.00);

-- Itens do Pedido
INSERT INTO itens_pedido (id_item_pedido, id_pedido, id_item_menu, quantidade, preco_total)
VALUES (seq_item_pedido.NEXTVAL, 1, 1, 2, 51.00);

-- Entregas
INSERT INTO entregas (id_entrega, id_pedido, quantidade, preco_unitario, status_entrega)
VALUES (seq_entrega.NEXTVAL, 1, 2, 25.50, 'ENTREGUE');

-- Pagamentos
INSERT INTO pagamentos (id_pagamento, id_pedido, forma_pagamento, valor_pago)
VALUES (seq_pagamento.NEXTVAL, 1, 'Pix', 46.00);

-- Logs
INSERT INTO logs (id_log, tabela, acao)
VALUES (seq_log.NEXTVAL, 'pedidos', 'Pedido criado com status ENTREGUE');
